describe('Coupon Code Validation', () => {
    beforeEach(() => {
        cy.visit('/checkout'); // Adjust the URL to your checkout page
    });

    it('should display an error message for an invalid coupon code', () => {
        cy.get('input[name="couponCode"]').type('INVALIDCODE');
        cy.get('button[type="submit"]').click();
        cy.get('.error-message').should('be.visible').and('contain', 'Invalid coupon code');
    });

    it('should not display an error message for a valid coupon code', () => {
        cy.get('input[name="couponCode"]').type('VALIDCODE'); // Replace with an actual valid code
        cy.get('button[type="submit"]').click();
        cy.get('.error-message').should('not.exist');
    });
});
